struct polar convert(struct rectangular point);
int main(void) {
    struct rectangular point;
    if (scanf("%lf %lf", &point.x, &point.y) != 2 ||
        !isfinite(point.x) || !isfinite(point.y) || fabs(point.x) > 1e6 || fabs(point.y) > 1e6) return 1;
    struct polar answer = convert(point);
