#include <stdio.h>
#include <stdarg.h>
double sum(int count, ...);
int main(void) {
    double three = sum(3, 1.5, 2.5, 4.0);
    double six = sum(6, 0.5, 1.5, 2.5, 3.5, 4.5, 5.5);
    printf("three=%.1f six=%.1f\n", three, six);
    return 0;
}
double sum(int count, ...) {
    if (count < 0) return 0.0;
    va_list arguments;
    va_start(arguments, count);
    double total = 0.0;
    for (int i = 0; i < count; i++) total += va_arg(arguments, double);
    va_end(arguments);
    return total;
}

