#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
int compare_int(const void *left, const void *right)
{
    const int *a = left;
    const int *b = right;
    return (*a > *b) - (*a < *b);
}
int main(void)
{
    int values[] = {INT_MAX, 4, INT_MIN, 0, -2, 4};
    size_t count = sizeof values / sizeof values[0];
    qsort(values, count, sizeof values[0], compare_int);
    for (size_t i = 0; i < count; ++i)
        printf("%d\n", values[i]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct name {
    char first[16];
    char last[16];
};
int compare_name(const void *left, const void *right)
{
    const struct name *a = left;
    const struct name *b = right;
    int order = strcmp(a->last, b->last);
    return order != 0 ? order : strcmp(a->first, b->first);
}
int main(void)
{
    struct name people[] = {{"Zoe", "Wu"}, {"Bo", "Lin"}, {"Ada", "Lin"}};
    size_t count = sizeof people / sizeof people[0];
    qsort(people, count, sizeof people[0], compare_name);
    for (size_t i = 0; i < count; ++i)
        printf("%s %s\n", people[i].first, people[i].last);
    return 0;
}

